typedef struct Node{int data;struct Node*left,*right;}Node;
int leafCount(Node*r){
    if(!r)return 0;                      // 空树
    if(!r->left && !r->right)return 1;   // 叶结点只有自己
    return leafCount(r->left)+leafCount(r->right);
